import AppKit

/// 剪贴板监听：NSPasteboard 没有变化通知，只能轮询 `changeCount`（0.35s，够快且成本可忽略）。
/// 受「启用剪贴板历史」开关控制，关闭时定时器完全移除。
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    /// 开关变化通知：由 SettingsStore.clipboardEnabled 的 didSet 触发
    /// （监听器、全局热键管理器、面板控制器共同监听）
    static let didChangeNotification = Notification.Name("zeroflow.clipboardEnabledDidChange")

    /// 密码管理器/系统标记为机密、瞬态、自动生成的内容一律不记录
    private static let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    private var timer: Timer?
    private var lastChangeCount = NSPasteboard.general.changeCount

    private init() {
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(handleDidChange),
            name: Self.didChangeNotification,
            object: nil
        )
    }

    func reapply() {
        if SettingsStore.shared.clipboardEnabled {
            start()
        } else {
            stop()
        }
    }

    /// 本 app 自己写剪贴板（粘贴）后调用：把基线推进到当前计数，避免把自己的写入再记一遍
    func markCurrentChangeCountAsHandled() {
        lastChangeCount = NSPasteboard.general.changeCount
    }

    @objc private func handleDidChange() {
        reapply()
    }

    // MARK: - 轮询

    private func start() {
        guard timer == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount
        let timer = Timer(timeInterval: 0.35, repeats: true) { [weak self] _ in
            self?.poll()
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
        ZSLog("clipboard: monitor started")
    }

    private func stop() {
        timer?.invalidate()
        timer = nil
        ZSLog("clipboard: monitor stopped")
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount

        let types = Set(pasteboard.types?.map(\.rawValue) ?? [])
        guard types.isDisjoint(with: Self.excludedTypes) else {
            ZSLog("clipboard: skip excluded pasteboard content")
            return
        }
        let sourceApp = NSWorkspace.shared.frontmostApplication?.localizedName ?? ""

        if let payload = imagePayload(from: pasteboard, types: types) {
            ClipboardHistoryStore.shared.addImage(pngData: payload.data,
                                                  pixelSize: payload.size,
                                                  sourceApp: sourceApp)
            return
        }
        if let text = pasteboard.string(forType: .string) {
            ClipboardHistoryStore.shared.addText(text, sourceApp: sourceApp)
        }
    }

    /// 图片优先于文本：浏览器/截图工具复制图片时通常同时带 tiff/png 与空串或 URL 文本
    private func imagePayload(from pasteboard: NSPasteboard,
                              types: Set<String>) -> (data: Data, size: CGSize)? {
        if types.contains(NSPasteboard.PasteboardType.png.rawValue),
           let data = pasteboard.data(forType: .png),
           let size = Self.pixelSize(ofPNG: data) {
            return (data, size)
        }
        guard types.contains(NSPasteboard.PasteboardType.tiff.rawValue),
              let tiff = pasteboard.data(forType: .tiff),
              let bitmap = NSBitmapImageRep(data: tiff),
              let png = bitmap.representation(using: .png, properties: [:])
        else { return nil }
        return (png, CGSize(width: bitmap.pixelsWide, height: bitmap.pixelsHigh))
    }

    private static func pixelSize(ofPNG data: Data) -> CGSize? {
        guard let bitmap = NSBitmapImageRep(data: data) else { return nil }
        return CGSize(width: bitmap.pixelsWide, height: bitmap.pixelsHigh)
    }
}
